/**
 * Reference data for the Windows error code lookup. Common codes only: an
 * entry is here because its number, name and meaning are well established.
 * Meanings are summaries in our own words, not the system message text.
 */
export interface CodeEntry {
  code: number;
  name: string;
  meaning: string;
  /** What an admin should look at. Only set where there is something specific to say. */
  check?: string;
}

function e(code: number, name: string, meaning: string, check?: string): CodeEntry {
  return check ? { code, name, meaning, check } : { code, name, meaning };
}

